    stepsCount: 6,
    procedure: [
      {
        id: 'step-1-1',
        stepNumber: 1,
        stepTitle: 'Inspection Machine Setup & Lighting Calibration',
        actionDetails: 'Engage motor drive and set speed between 12-15 yards/minute. Measure surface illumination with calibrated lux meter at left, center, right viewing zones.',
        qualityControlPoints: 'Lux level >= 1,075 lux at table surface across all viewing zones.',
        responsibleRole: 'Fabric QC Inspector',
        safetyInstructions: 'Test emergency trip bar prior to powering on motor.',
        requiredTools: 'Digital Lux Meter',
      },
      {
        id: 'step-1-2',
        stepNumber: 2,
        stepTitle: 'Roll Header Tag & Physical Verification',
        actionDetails: 'Match supplier roll packing slip, dyelot number, gross weight, and ticket yardage against Garments ERP Purchase Order.',
        qualityControlPoints: 'Gross weight within +/- 1.5% of ERP scale reading.',
        responsibleRole: 'Fabric QC Inspector',
        requiredTools: 'Floor scale & barcode scanner',
      },
      {
        id: 'step-1-3',
        stepNumber: 3,
        stepTitle: 'Continuous 4-Point Surface Defect Scoring',
        actionDetails: 'Examine full fabric face. Score defects: 1 pt (<3 in), 2 pts (3-6 in), 3 pts (6-9 in), 4 pts (>9 in or holes). Insert arrow stickers at selvedge corresponding to each defect.',
        qualityControlPoints: 'Maximum 4 penalty points per linear yard.',
        responsibleRole: 'Fabric QC Inspector',
        safetyInstructions: 'Wear lint-free nitrile gloves.',
        requiredTools: 'Adhesive selvedge arrow stickers',
      },
      {
        id: 'step-1-4',
        stepNumber: 4,
        stepTitle: 'Cuttable Width & Bowing / Skewing Measurement',
        actionDetails: 'Measure width inside selvedges at beginning, 50% yardage, and tail of roll. Measure weft bowing or spirality percentage using steel square.',
        qualityControlPoints: 'Cuttable width >= PO spec; bowing <= 2.5% for woven, <= 4.0% for knits.',
        responsibleRole: 'Fabric QC Inspector',
        requiredTools: 'Calibrated steel rule & square',
      },
      {
        id: 'step-1-5',
        stepNumber: 5,
        stepTitle: 'Shade Swatch Cut & Light Booth Evaluation',
        actionDetails: 'Cut 6-inch full-width swatch from roll header and footer. Fold in half and evaluate edge-to-edge & center-to-edge shade against approved lab dip in spectral light booth.',
        qualityControlPoints: 'Shade variation Grade 4.5+ on AATCC Gray Scale.',
        responsibleRole: 'Shade Evaluator',
        requiredTools: 'Macbeth Spectralight Booth (D65 / TL84 / CWF)',
      },
      {
        id: 'step-1-6',
        stepNumber: 6,
        stepTitle: 'Points Calculation & Final Roll Disposition',
        actionDetails: 'Calculate penalty score: (Total Points x 3600) / (Inspected Yards x Cuttable Width Inches). Enter score in ERP and affix Green PASS, Red REJECT, or Yellow HOLD roll tag.',
        qualityControlPoints: 'Green PASS tag affixed securely if score <= 28.0.',
        responsibleRole: 'Warehouse Quality Manager',
        requiredTools: 'Color status roll tags',
      },
    ],
